    'welcome.signIn': 'Connexion',
    'welcome.getStarted': 'Commencer',
    'welcome.scheduleDemo': 'Planifier une démo',
    'welcome.heroTitle': "L'outil tout-en-un pour orchestrer vos ministères sans effort",
    'welcome.heroSubtitle': "Prenez le contrôle de l'organisation de votre église sans perdre de temps.",
    'welcome.valuePropsTitle': '',
    'welcome.valuePropsSubtitle': '',
    'welcome.valueProp1Title': 'Opérationnel immédiatement',
    'welcome.valueProp1Desc': "Profitez de 14 départements préconfigurés et ajustables à l'image de votre communauté.",
    'welcome.valueProp2Title': "Zéro erreur d'affectation",
    'welcome.valueProp2Desc': "Recevez des alertes automatiques en cas de double programmation ou d'absence signalée.",
    'welcome.valueProp3Title': 'Centralisation totale',
    'welcome.valueProp3Desc': "Un planning unique pour orchestrer l'ensemble de vos équipes pour chaque service.",
    'welcome.aboutTitle': 'Qui sommes-nous',
    'welcome.aboutBody': "ChurchOnPoint est le système de gestion d'église conçu par AliviaTech. Le projet a commencé comme système de planification et de gestion des membres pour une seule église, et a grandi à partir de besoins réels : un moyen de suivre un remplacement promis quand quelqu'un ne peut pas honorer son créneau, un reçu fiscal officiel en fin d'année, un lien public pour prendre rendez-vous avec un pasteur, un comptage rapide à la porte un dimanche. Quand cette église a ouvert un second site, le même système a développé une façon de gérer plusieurs extensions d'une même dénomination — chacune avec sa propre adresse et ses propres administrateurs — sous une seule connexion, avec un Super Administrateur Général, un Superviseur Général et un Secrétaire Général qui peuvent agir sur toutes les extensions.",
    'welcome.featuresTitle': "Ce qu'il y a vraiment dedans",
    'welcome.featuresSubtitle': "Pas une liste de fonctionnalités générique — voici ce que l'application fait aujourd'hui.",
    'welcome.featureDeptsTitle': 'Ministères, prêts dès le premier jour',
    'welcome.featureDeptsDesc': '{list} — déjà en place dès l’inscription d’une église, pas une page blanche à configurer.',
    'welcome.featureSchedulingTitle': 'Une planification qui détecte les conflits',
    'welcome.featureSchedulingDesc': "Assigner quelqu'un déjà programmé dans un autre département ce jour-là l'indique directement dans la liste de sélection. Signaler une absence après avoir été programmé demande une confirmation, et avertit automatiquement le chef de département. Quelqu'un qui a déjà dit qu'il ne pouvait pas venir ne peut pas être programmé par-dessus.",
    'welcome.featureExtensionsTitle': "Extensions d'église",
    'welcome.featureExtensionsDesc': "Une dénomination, plusieurs sites physiques, chacun avec sa propre adresse et ses propres administrateurs — avec un Super Administrateur Général, un Superviseur Général et un Secrétaire Général qui ont un accès réel à chaque extension, pas un simple résumé en lecture seule.",
    'welcome.featureTaxTitle': 'Reçus fiscaux',
    'welcome.featureTaxDesc': "Suivez les dons tout au long de l'année et émettez des reçus fiscaux officiels et numérotés en fin d'année, que les membres peuvent utiliser pour leur déclaration.",
    'welcome.featureBookingTitle': 'Réservation de rendez-vous pastoraux',
    'welcome.featureBookingDesc': "Un lien public où n'importe qui peut réserver un rendez-vous avec un pasteur selon les disponibilités réelles fixées par l'église — sans échanges de courriels interminables.",
    'welcome.featureServiceProgramTitle': 'Programme du service',
    'welcome.featureServiceProgramDesc': "Un seul programme pour une date donnée, regroupant tous les départements — qui prêche, qui est aux diapositives, qui est à la porte — plutôt que de vérifier cinq horaires séparés.",
    'welcome.featureHeadcountTitle': 'Comptage des présences',
    'welcome.featureHeadcountDesc': "Un compteur tactile pour la présence du dimanche, partageable par code QR pour que plusieurs personnes puissent compter en même temps.",
    'welcome.featureBudgetTitle': 'Budget et finances',
    'welcome.featureBudgetDesc': "Demandes de fonds, remboursements et budgets par département, avec notes de révision et export PDF.",
    'welcome.featureIdCardTitle': 'Cartes de membre et suivi des visiteurs',
    'welcome.featureIdCardDesc': "Cartes d'identité avec photo, insignes de département (et le nom de l'extension, pour une dénomination qui en compte plus d'une). Un espace de suivi des visiteurs qui accompagne un nouveau venu depuis son arrivée jusqu'à son intégration dans un département.",
    'welcome.pricingTitle': 'Tarifs',
    'welcome.pricingSubtitle': "Chaque forfait commence par un essai gratuit de 30 jours. Ajoutez votre carte pour commencer — vous ne serez pas facturé avant la fin de votre essai.",
    'welcome.loadingPlans': 'Chargement des forfaits…',
    'welcome.pricingFailed': "Impossible de charger les tarifs pour le moment — veuillez réessayer sous peu, ou nous contacter ci-dessous.",
    'welcome.contactTitle': 'Parlez-nous',
    'welcome.contactBody': "Des questions, envie d'une démonstration, ou prêt à faire passer votre église sur ChurchOnPoint ? Envoyez-nous un message et nous vous répondrons — ou contactez-nous directement ci-dessous.",
    'welcome.previewMailtoNote': "(Les liens courriel/téléphone sont affichés en texte simple dans cet aperçu — les liens mailto:/tel: ne sont pas fiables dans un cadre d'aperçu, mais fonctionnent normalement sur la page publiée réelle.)",
