export function getLang() {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (SUPPORTED.includes(stored)) return stored;
  const browserLang = (navigator.language || 'en').slice(0, 2);
  return SUPPORTED.includes(browserLang) ? browserLang : 'en';
}

export function setLang(lang) {
  if (!SUPPORTED.includes(lang) || lang === getLang()) return;
  localStorage.setItem(STORAGE_KEY, lang);
  document.documentElement.lang = lang;
  window.dispatchEvent(new CustomEvent('choir-hub:langchange'));
}

export function onLangChange(fn) {
  window.addEventListener('choir-hub:langchange', fn);
}

export function t(key, vars) {
  const lang = getLang();
  const dict = TRANSLATIONS[lang] || TRANSLATIONS.en;
  let str = labelOverrides[lang]?.[key] ?? dict[key] ?? TRANSLATIONS.en[key] ?? key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      str = str.replaceAll(`{${k}}`, v);
    }
  }
  return str;
}

// French treats 0 as singular too ("0 modification"), unlike English.
function pluralForm(lang, count) {
  return lang === 'fr' ? (count <= 1 ? 'one' : 'other') : (count === 1 ? 'one' : 'other');
}

export function tn(key, count, vars = {}) {
  const form = pluralForm(getLang(), count);
  return t(`${key}_${form}`, { count, ...vars });
}

export function monthName(monthIndex) {
  return t(`month.${monthIndex}`);
}

export function voicePartLabel(part) {
  return part ? t(`voicePart.${part}`) : part;
}

export function roleLabel(role) {
  return role ? t(`role.${role}`) : role;
}

export function departmentLabel(key) {
  return key ? t(`department.${key}`) : key;
}

// Emoji per department key -- purely a visual lookup (sidebar icon,
// dashboard header icon), no schema column for it. departments.key is
// free text, slugified from whatever name an admin picks in
// createDepartmentModal.js, so this can never be exhaustive --
// unrecognized keys fall back to a plain building icon.
const DEPARTMENT_ICONS = {
  choir: '🎵',
  cleaning: '🧹',
  finance: '💰',
  security: '🛡️',
  ushers: '🧍',
  intercession: '🙏',
  media: '🎥',
  media_tech: '🎥',
  evangelism: '📢',
  church_program: '📅',
  preaching: '📖',
  social: '🎉',
  sunday_school: '🎒',
  interpreting: '🗣️',
  welcoming_socialisation: '🤝',
  ecodem: '🌱',
};
export function departmentIcon(key) {
  return DEPARTMENT_ICONS[key] || '⛪';
}

// The built-in (pre-override) text for a key in each language — used
// by menuCustomizer.js to pre-fill its form and to power "Reset to
// default", neither of which should reflect any override already in
// effect.
export function getBuiltInLabel(key) {
  return { en: TRANSLATIONS.en[key] ?? key, fr: TRANSLATIONS.fr[key] ?? key };
}

export function mediaTechRoleLabel(role) {
  return role ? t(`mediaTech.role.${role}`) : role;
}

export function ecodemAgeGroupLabel(group) {
  return group ? t(`ecodem.ageGroup.${group}`) : group;
}

// Applies text/placeholder/aria-label translations to every element
// carrying a data-i18n* attribute — used for the static index.html shell.
export function applyStaticTranslations(root = document) {
  root.querySelectorAll('[data-i18n]').forEach((el) => {
    el.textContent = t(el.dataset.i18n);
  });
  root.querySelectorAll('[data-i18n-placeholder]').forEach((el) => {
    el.placeholder = t(el.dataset.i18nPlaceholder);
  });
  root.querySelectorAll('[data-i18n-aria-label]').forEach((el) => {
    el.setAttribute('aria-label', t(el.dataset.i18nAriaLabel));
  });
}
